"""
Pytest configuration and shared fixtures for FastAPI application tests (Stage A & C).
"""

import asyncio
import pytest
from fastapi.testclient import TestClient
from sqlalchemy import select, delete

from app.main import create_app
from app.common.dependencies import get_repository, get_fixture_repository

PRESERVED_CORE_HANDLES = {'asha', 'deepu', 'ani', 'virat', 'sneha', 'vivek', 'sand', 't1234'}


async def _cleanup_test_database_state():
    """Removes temporary test accounts and test posts generated by pytest runs."""
    from app.database import get_async_sessionmaker
    from app.models.user import User
    from app.models.post import Post
    from app.models.media import PostMedia
    from app.models.like import PostLike
    from app.models.follow import Follow
    from app.models.session import Session
    from app.models.notification import Notification

    session_factory = get_async_sessionmaker()
    async with session_factory() as s:
        res = await s.execute(select(User.id).where(User.handle.in_(PRESERVED_CORE_HANDLES)))
        keep_ids = [row[0] for row in res.all()]
        if not keep_ids:
            return

        subq = select(Post.id).where(~Post.author_id.in_(keep_ids))
        await s.execute(delete(Notification).where(~Notification.recipient_id.in_(keep_ids) | ~Notification.actor_id.in_(keep_ids)))
        await s.execute(delete(Session).where(~Session.user_id.in_(keep_ids)))
        await s.execute(delete(Follow).where(~Follow.follower_id.in_(keep_ids) | ~Follow.following_id.in_(keep_ids)))
        await s.execute(delete(PostLike).where(~PostLike.user_id.in_(keep_ids)))
        await s.execute(delete(PostMedia).where(PostMedia.post_id.in_(subq)))
        await s.execute(delete(Post).where(~Post.author_id.in_(keep_ids)))
        await s.execute(delete(User).where(~User.id.in_(keep_ids)))
        await s.commit()


@pytest.fixture(autouse=True, scope="session")
def protect_database_from_test_pollution():
    """Autouse fixture that runs at pytest start and end to guarantee zero test account residue."""
    loop = asyncio.new_event_loop()
    try:
        loop.run_until_complete(_cleanup_test_database_state())
    except Exception:
        pass
    yield
    try:
        loop.run_until_complete(_cleanup_test_database_state())
    except Exception:
        pass
    finally:
        loop.close()


@pytest.fixture
def app():
    """Returns a fresh FastAPI application instance configured for tests."""
    application = create_app()
    # Default repository for Stage A unit tests is the deterministic FixtureRepository
    application.dependency_overrides[get_repository] = get_fixture_repository
    yield application
    application.dependency_overrides.clear()


@pytest.fixture
def client(app):
    """Provides a TestClient for synchronous API testing."""
    with TestClient(app) as test_client:
        yield test_client

